//
//  HomeShelvesSection.swift
//  Reverie
//
//  Vertically-stacked shelves that replace the single "Discover" rail.
//  Each shelf is a horizontal carousel of cards. Shelves are generated by
//  RecommendationEngine.generateShelves using different seed strategies
//  ("Pick up again", "Because you played X", "Fresh finds", etc.).
//
//  Tapping a card plays immediately — library tracks play locally, remote
//  recommendations stream via AudioPlayer.streamRemote. Long-press opens
//  an options sheet (Save to library / Download).
//

import SwiftUI
import SwiftData
#if canImport(UIKit)
import UIKit
#elseif canImport(AppKit)
import AppKit
#endif

struct HomeShelvesSection: View {
    @Environment(\.modelContext) private var modelContext
    let audioPlayer: AudioPlayer

    @State private var shelves: [HomeShelf] = []
    @State private var isLoading = false
    @State private var selectedRemote: ShelfItem?

    @AppStorage("tuningPrompt") private var tuningPrompt = ""

    private let engine = RecommendationEngine()

    var body: some View {
        VStack(alignment: .leading, spacing: 28) {
            if isLoading && shelves.isEmpty {
                loadingHeader
            }

            ForEach(shelves) { shelf in
                shelfView(shelf)
            }

            if !isLoading && shelves.isEmpty {
                emptyState
            }
        }
        .task {
            await loadShelves()
        }
        .refreshable {
            await loadShelves()
        }
        .sheet(item: $selectedRemote) { item in
            ShelfItemOptionsSheet(
                item: item,
                audioPlayer: audioPlayer,
                modelContext: modelContext
            )
            #if os(iOS)
            .presentationDetents([.medium])
            .presentationDragIndicator(.visible)
            #else
            .frame(minWidth: 380, minHeight: 300)
            #endif
        }
    }

    // MARK: - Shelves

    @ViewBuilder
    private func shelfView(_ shelf: HomeShelf) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            shelfHeader(shelf)

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(alignment: .top, spacing: 14) {
                    ForEach(shelf.items) { item in
                        shelfCard(item)
                    }
                }
                .padding(.horizontal, 2)
            }
        }
    }

    private func shelfHeader(_ shelf: HomeShelf) -> some View {
        HStack(alignment: .firstTextBaseline, spacing: 8) {
            Image(systemName: shelf.systemImage)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(CanopyTheme.Palette.green)

            VStack(alignment: .leading, spacing: 2) {
                Text(shelf.title)
                    .font(CanopyTheme.Typography.title2)
                    .foregroundStyle(CanopyTheme.Palette.ink)
                    .lineLimit(1)
                if let subtitle = shelf.subtitle, !subtitle.isEmpty {
                    Text(subtitle)
                        .font(CanopyTheme.Typography.caption)
                        .foregroundStyle(CanopyTheme.Palette.muted)
                        .lineLimit(1)
                }
            }
            Spacer()
        }
    }

    private func shelfCard(_ item: ShelfItem) -> some View {
        Button {
            Task { await play(item) }
        } label: {
            VStack(alignment: .leading, spacing: 8) {
                artworkView(item)
                    .frame(width: 140, height: 140)
                    .clipShape(RoundedRectangle(cornerRadius: 12, style: .continuous))
                    .overlay(
                        RoundedRectangle(cornerRadius: 12, style: .continuous)
                            .strokeBorder(CanopyTheme.Palette.hair, lineWidth: 0.5)
                    )
                    .overlay(alignment: .bottomTrailing) {
                        // Subtle play-affordance on hover — matches Apple
                        // Music's card treatment.
                        Image(systemName: "play.circle.fill")
                            .font(.system(size: 30))
                            .foregroundStyle(.white)
                            .shadow(color: .black.opacity(0.3), radius: 4, y: 2)
                            .padding(8)
                    }

                VStack(alignment: .leading, spacing: 2) {
                    Text(item.title)
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(CanopyTheme.Palette.ink)
                        .lineLimit(1)
                    Text(item.artist)
                        .font(.caption2)
                        .foregroundStyle(CanopyTheme.Palette.muted)
                        .lineLimit(1)
                }
                .frame(width: 140, alignment: .leading)
            }
        }
        .buttonStyle(.plain)
        .contentShape(Rectangle())
        .onLongPressGesture(minimumDuration: 0.4) {
            HapticManager.shared.longPress()
            selectedRemote = item
        }
        .accessibilityLabel("\(item.title) by \(item.artist)")
        .accessibilityHint("Double tap to play. Long press for options.")
    }

    @ViewBuilder
    private func artworkView(_ item: ShelfItem) -> some View {
        if let data = item.artData {
            #if canImport(UIKit)
            if let ui = UIImage(data: data) {
                Image(uiImage: ui).resizable().aspectRatio(contentMode: .fill)
            } else {
                placeholder
            }
            #elseif canImport(AppKit)
            if let ns = NSImage(data: data) {
                Image(nsImage: ns).resizable().aspectRatio(contentMode: .fill)
            } else {
                placeholder
            }
            #endif
        } else if let url = item.thumbnailURL {
            AsyncImage(url: url) { phase in
                switch phase {
                case .success(let image):
                    image.resizable().aspectRatio(contentMode: .fill)
                case .failure, .empty:
                    placeholder
                @unknown default:
                    placeholder
                }
            }
        } else {
            placeholder
        }
    }

    private var placeholder: some View {
        LinearGradient(
            colors: [
                CanopyTheme.Palette.mintVeil,
                CanopyTheme.Palette.mint.opacity(0.25)
            ],
            startPoint: .topLeading,
            endPoint: .bottomTrailing
        )
        .overlay {
            Image(systemName: "music.note")
                .font(.title)
                .foregroundStyle(CanopyTheme.Palette.green)
        }
    }

    // MARK: - Transient states

    private var loadingHeader: some View {
        HStack(spacing: 10) {
            ProgressView()
                .controlSize(.small)
                .tint(CanopyTheme.Palette.green)
            Text("Building your home page…")
                .font(CanopyTheme.Typography.caption)
                .foregroundStyle(CanopyTheme.Palette.muted)
            Spacer()
        }
        .padding(.vertical, 12)
    }

    private var emptyState: some View {
        VStack(spacing: 10) {
            Image(systemName: "wifi.exclamationmark")
                .font(.title2)
                .foregroundStyle(.secondary)
            Text("We couldn't reach recommendations right now.")
                .font(.subheadline.weight(.medium))
                .foregroundStyle(.secondary)
                .multilineTextAlignment(.center)
            Button {
                Task { await loadShelves() }
            } label: {
                Text("Try again").font(.caption.weight(.semibold))
            }
            .buttonStyle(.bordered)
            .controlSize(.small)
        }
        .frame(maxWidth: .infinity)
        .padding(.vertical, 40)
    }

    // MARK: - Actions

    private func loadShelves() async {
        isLoading = true
        let filters = TuningParser.parse(tuningPrompt)
        let result = await engine.generateShelves(
            modelContext: modelContext,
            tuningFilters: filters
        )
        shelves = result
        isLoading = false
    }

    private func play(_ item: ShelfItem) async {
        if let track = item.libraryTrack {
            await audioPlayer.playTrack(track, modelContext: modelContext)
            return
        }
        guard let videoID = item.videoID else { return }
        await audioPlayer.streamRemote(
            videoID: videoID,
            title: item.title,
            artist: item.artist,
            thumbnailURL: item.thumbnailURL
        )
    }
}

// MARK: - Options Sheet

/// Long-press sheet — "Play" / "Save to library" / "Go to artist". Mirrors
/// Apple Music's long-press menu pattern.
private struct ShelfItemOptionsSheet: View {
    let item: ShelfItem
    let audioPlayer: AudioPlayer
    let modelContext: ModelContext
    @Environment(\.dismiss) private var dismiss
    @State private var isSaving = false

    var body: some View {
        VStack(spacing: 20) {
            RoundedRectangle(cornerRadius: 12)
                .fill(
                    LinearGradient(
                        colors: [Color.accentColor.opacity(0.25), Color.accentColor.opacity(0.08)],
                        startPoint: .topLeading, endPoint: .bottomTrailing
                    )
                )
                .frame(width: 120, height: 120)
                .overlay {
                    AsyncImage(url: item.thumbnailURL) { phase in
                        if case .success(let image) = phase {
                            image.resizable().aspectRatio(contentMode: .fill)
                        } else {
                            Image(systemName: "music.note").font(.title)
                        }
                    }
                }
                .clipShape(RoundedRectangle(cornerRadius: 12))

            VStack(spacing: 4) {
                Text(item.title).font(.headline).multilineTextAlignment(.center)
                Text(item.artist).font(.subheadline).foregroundStyle(.secondary)
            }

            VStack(spacing: 10) {
                Button {
                    Task {
                        await play()
                        dismiss()
                    }
                } label: {
                    Label("Play now", systemImage: "play.fill")
                        .font(.headline)
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 10)
                }
                .buttonStyle(.borderedProminent)

                if item.libraryTrack == nil {
                    Button {
                        Task { await save() }
                    } label: {
                        HStack {
                            if isSaving {
                                ProgressView().controlSize(.small)
                            } else {
                                Image(systemName: "arrow.down.to.line")
                            }
                            Text(isSaving ? "Saving…" : "Save to library")
                                .font(.subheadline.weight(.semibold))
                        }
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 10)
                    }
                    .buttonStyle(.bordered)
                    .disabled(isSaving)
                }
            }
            .padding(.horizontal)

            Spacer()
        }
        .padding(.top, 24)
        .frame(maxWidth: .infinity, maxHeight: .infinity)
    }

    private func play() async {
        if let track = item.libraryTrack {
            await audioPlayer.playTrack(track, modelContext: modelContext)
            return
        }
        guard let videoID = item.videoID else { return }
        await audioPlayer.streamRemote(
            videoID: videoID,
            title: item.title,
            artist: item.artist,
            thumbnailURL: item.thumbnailURL
        )
    }

    private func save() async {
        guard let videoID = item.videoID else { return }
        isSaving = true
        defer { isSaving = false }

        let track = ReverieTrack(
            title: item.title,
            artist: item.artist,
            album: "",
            durationSeconds: 0,
            albumArtData: item.artData,
            youtubeVideoID: videoID,
            downloadState: .queued
        )
        modelContext.insert(track)
        try? modelContext.save()
        try? await audioPlayer.downloadManager.downloadTrack(track, modelContext: modelContext)
    }
}
